	(2485,33636,'recipe_instructions','a:7:{i:0;a:3:{s:5:\"group\";s:42:\"Fresh Pesto (you can make this in advance)\";s:11:\"description\";s:123:\"We\'ll be using a food processor to make the pesto. Put the garlic, pine kernels and some salt in there and process briefly.\";s:5:\"image\";s:0:\"\";}i:1;a:3:{s:5:\"group\";s:42:\"Fresh Pesto (you can make this in advance)\";s:11:\"description\";s:85:\"Add the basil leaves (but keep some for the presentation) and blend to a green paste.\";s:5:\"image\";s:0:\"\";}i:2;a:3:{s:5:\"group\";s:42:\"Fresh Pesto (you can make this in advance)\";s:11:\"description\";s:82:\"While processing, gradually add the olive oil and finally add the Parmesan cheese.\";s:5:\"image\";s:0:\"\";}i:3;a:3:{s:5:\"group\";s:18:\"Finishing the dish\";s:11:\"description\";s:75:\"Bring a pot of salted water to the boil and cook your tagliatelle al dente.\";s:5:\"image\";s:0:\"\";}i:4;a:3:{s:5:\"group\";s:18:\"Finishing the dish\";s:11:\"description\";s:62:\"Use the cooking time of the pasta to sauté your bacon strips.\";s:5:\"image\";s:0:\"\";}i:5;a:3:{s:5:\"group\";s:18:\"Finishing the dish\";s:11:\"description\";s:116:\"After about 8 to 10 minutes, the pasta should be done. Drain it and put it back in the pot to mix it with the pesto.\";s:5:\"image\";s:0:\"\";}i:6;a:3:{s:5:\"group\";s:18:\"Finishing the dish\";s:11:\"description\";s:53:\"Present the dish with some fresh basil leaves on top.\";s:5:\"image\";s:0:\"\";}}'),
