	(2549,33642,'recipe_ingredients','a:15:{i:0;a:7:{s:6:\"amount\";s:1:\"5\";s:4:\"unit\";s:4:\"cups\";s:10:\"ingredient\";s:9:\"wild rice\";s:5:\"notes\";s:6:\"cooked\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:86;s:17:\"amount_normalized\";d:5;}i:1;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"cup\";s:10:\"ingredient\";s:9:\"mushrooms\";s:5:\"notes\";s:12:\"finely diced\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:87;s:17:\"amount_normalized\";d:1;}i:2;a:7:{s:6:\"amount\";s:1:\"4\";s:4:\"unit\";s:0:\"\";s:10:\"ingredient\";s:4:\"eggs\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:88;s:17:\"amount_normalized\";d:4;}i:3;a:7:{s:6:\"amount\";s:5:\"1 1/2\";s:4:\"unit\";s:4:\"cups\";s:10:\"ingredient\";s:10:\"mayonnaise\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:89;s:17:\"amount_normalized\";d:1.5;}i:4;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"cup\";s:10:\"ingredient\";s:17:\"panko breadcrumbs\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:90;s:17:\"amount_normalized\";d:1;}i:5;a:7:{s:6:\"amount\";s:1:\"4\";s:4:\"unit\";s:3:\"tsp\";s:10:\"ingredient\";s:5:\"cumin\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:91;s:17:\"amount_normalized\";d:4;}i:6;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"tsp\";s:10:\"ingredient\";s:4:\"salt\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:92;s:17:\"amount_normalized\";d:1;}i:7;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"tsp\";s:10:\"ingredient\";s:6:\"pepper\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:93;s:17:\"amount_normalized\";d:1;}i:8;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"tsp\";s:10:\"ingredient\";s:13:\"garlic powder\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i: