	(2600,33649,'recipe_ingredients','a:15:{i:0;a:7:{s:6:\"amount\";s:1:\"5\";s:4:\"unit\";s:4:\"cups\";s:10:\"ingredient\";s:9:\"wild rice\";s:5:\"notes\";s:6:\"cooked\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:86;s:17:\"amount_normalized\";d:5;}i:1;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"cup\";s:10:\"ingredient\";s:9:\"mushrooms\";s:5:\"notes\";s:12:\"finely diced\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:87;s:17:\"amount_normalized\";d:1;}i:2;a:7:{s:6:\"amount\";s:1:\"4\";s:4:\"unit\";s:0:\"\";s:10:\"ingredient\";s:4:\"eggs\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:88;s:17:\"amount_normalized\";d:4;}i:3;a:7:{s:6:\"amount\";s:5:\"1 1/2\";s:4:\"unit\";s:4:\"cups\";s:10:\"ingredient\";s:10:\"mayonnaise\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:89;s:17:\"amount_normalized\";d:1.5;}i:4;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"cup\";s:10:\"ingredient\";s:17:\"panko breadcrumbs\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:90;s:17:\"amount_normalized\";d:1;}i:5;a:7:{s:6:\"amount\";s:1:\"4\";s:4:\"unit\";s:3:\"tsp\";s:10:\"ingredient\";s:5:\"cumin\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:91;s:17:\"amount_normalized\";d:4;}i:6;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"tsp\";s:10:\"ingredient\";s:4:\"salt\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:92;s:17:\"amount_normalized\";d:1;}i:7;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"tsp\";s:10:\"ingredient\";s:6:\"pepper\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:93;s:17:\"amount_normalized\";d:1;}i:8;a:7:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"tsp\";s:10:\"ingredient\";s:13:\"garlic powder\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:94;s:17:\"amount_normalized\";d:1;}i:9;a:7:{s:6:\"amount\";s:3:\"1/2\";s:4:\"unit\";s:3:\"tsp\";s:10:\"ingredient\";s:7:\"cayenne\";s:5:\"notes\";s:18:\"optional, to taste\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:95;s:17:\"amount_normalized\";d:0.5;}i:10;a:7:{s:6:\"amount\";s:0:\"\";s:4:\"unit\";s:0:\"\";s:10:\"ingredient\";s:9:\"olive oil\";s:5:\"notes\";s:11:\"for the pan\";s:5:\"group\";s:15:\"For the burgers\";s:13:\"ingredient_id\";i:82;s:17:\"amount_normalized\";i:0;}i:11;a:7:{s:6:\"amount\";s:1:\"6\";s:4:\"unit\";s:0:\"\";s:10:\"ingredient\";s:11:\"burger buns\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:11:\"For serving\";s:13:\"ingredient_id\";i:96;s:17:\"amount_normalized\";d:6;}i:12;a:7:{s:6:\"amount\";s:0:\"\";s:4:\"unit\";s:0:\"\";s:10:\"ingredient\";s:7:\"lettuce\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:11:\"For serving\";s:13:\"ingredient_id\";i:97;s:17:\"amount_normalized\";i:0;}i:13;a:7:{s:6:\"amount\";s:1:\"6\";s:4:\"unit\";s:6:\"slices\";s:10:\"ingredient\";s:14:\"cheddar cheese\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:11:\"For serving\";s:13:\"ingredient_id\";i:98;s:17:\"amount_normalized\";d:6;}i:14;a:7:{s:6:\"amount\";s:0:\"\";s:4:\"unit\";s:0:\"\";s:10:\"ingredient\";s:14:\"barbecue sauce\";s:5:\"notes\";s:0:\"\";s:5:\"group\";s:11:\"For serving\";s:13:\"ingredient_id\";i:99;s:17:\"amount_normalized\";i:0;}}'),
	(2601,33649,'recipe_instructions','a:5:{i:0;a:3:{s:11:\"description\";s:20:\"Mix all ingredients.\";s:5:\"group\";s:0:\"\";s:5:\"image\";s:0:\"\";}i:1;a:3:{s:11:\"description\";s:203:\"Using a 1-cup measuring cup, scoop up rice mixture and form into patties. If the mixture is too wet, just add another 1/2 cup of panko or pop it in the fridge for a few minutes to help it stick together.\";s:5:\"group\";s:0:\"\";s:5:\"image\";s:0:\"\";}i:2;a:3:{s:11:\"description\";s:111:\"Heat a little bit of oil over medium high heat. Add the patties and pan fry until nicely browned on both sides.\";s:5:\"group\";s:0:\"\";s:5:\"image\";s:0:\"\";}i:3;a:3:{s:11:\"description\";s:187:\"Top with slices of Muenster cheese. Serve on a bun (or not!) with barbecue sauce, hot sauce, magic green sauce, ALL THE SAUCE. Also arugula, avocado, and beyond. You’ve only just begun.\";s:5:\"group\";s:0:\"\";s:5:\"image\";s:0:\"\";}i:4;a:3:{s:11:\"description\";s:58:\"Put lettuce, cheese, and BBQ sauce on the burgers and eat.\";s:5:\"group\";s:17:\"Build the burgers\";s:5:\"image\";s:0:\"\";}}'),
	(2602,33649,'recipe_notes','<ul>\r\n 	<li>I found that 1 1/2 cups raw wild rice was about the right amount to yield 5 cups cooked wild rice.</li>\r\n 	<li>This was served to us with a side of roasted cauliflower which was just total perfection. They went together beautifully.</li>\r\n</ul>\r\n<em>Italic text.</em> <strong>Bold Text.</strong>\r\n<p style=\"text-align: center;\">Centered text.</p>\r\n<p style=\"text-align: left;\"><a href=\"http://google.com\" rel=\"false\">Linked text.</a></p>\r\n\r\n<blockquote>\r\n<p style=\"text-align: left;\">Quoted text.</p>\r\n</blockquote>\r\n<ol>\r\n 	<li>To get your cheese nice and ooey-gooey, add it to the burgers for the last few minutes of pan frying and cover with a lid.</li>\r\n 	<li>To make ahead or gift to someone, just freeze the burgers on a sheet pan until individually frozen solid and then store together in a freezer bag.</li>\r\n 	<li>Worth noting that I have tried reducing the mayo but it never turns out as good. I do, however, add more mushrooms and as long as the ratios of all the other ingredients are as-written, it comes out great.</li>\r\n</ol>'),
