INSERT INTO `wptests_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`)
VALUES
	(33636,2,'2017-04-03 22:22:51','2017-04-03 22:22:51','<p>Use this like normal post content. The recipe will automatically be included at the end of the post, or wherever you place the shortcode:</p>[recipe]<br/><p>This text will appear below your recipe.</p>[wpurp-searchable-recipe]Demo Recipe - This must be the best demo recipe I have ever seen. I could eat this every single day. - tagliatelle, bacon (tiny strips), Fresh Pesto: garlic, pine kernels, basil leaves, olive oil (extra virgin), Parmesan cheese (freshly grated), Fresh Pesto (you can make this in advance): We&#039;ll be using a food processor to make the pesto. Put the garlic, pine kernels and some salt in there and process briefly.; Add the basil leaves (but keep some for the presentation) and blend to a green paste.; While processing, gradually add the olive oil and finally add the Parmesan cheese.; Finishing the dish: Bring a pot of salted water to the boil and cook your tagliatelle al dente.; Use the cooking time of the pasta to sauté your bacon strips.; After about 8 to 10 minutes, the pasta should be done. Drain it and put it back in the pot to mix it with the pesto.; Present the dish with some fresh basil leaves on top.;  - Use this section for whatever you like.[/wpurp-searchable-recipe]','Demo Recipe','','private','open','closed','','demo-recipe','','','2017-04-03 22:22:51','2017-04-03 22:22:51','',0,'http://tasty.handbuilt.co/recipe/demo-recipe/',0,'recipe','',0),
